    @pydantic.field_validator("string_value", mode="before")
    @classmethod
    def _set_string_value(cls, v: typing.Optional[str], info: pydantic.ValidationInfo) -> str:
        # If the caller supplies a string_value, keep it; otherwise derive from numeric value.
        if v is not None:
            return v
        # ``value`` is guaranteed to be present because it's a required field.
        numeric = info.data.get("value")
        # Treat any truthy numeric (1) as True, otherwise False. The API defines 1/0.
        return "True" if numeric == 1 else "False"
