  "test": "import pytest
import typing
import pydantic

from langfuse.api.commons.types.boolean_score import BooleanScore

def test_boolean_score_auto_string_true():
    score = BooleanScore(value=1)
    assert isinstance(score, BooleanScore)
    assert score.string_value == "True"
    assert score.value == 1

def test_boolean_score_auto_string_false():
    score = BooleanScore(value=0)
    assert score.string_value == "False"
    assert score.value == 0

def test_boolean_score_explicit_string_overrides():
    score = BooleanScore(value=1, string_value="custom")
    assert score.string_value == "custom"
    assert score.value == 1
